// The plot bridge (extracted from the old tools.js). Images generated by a
// tool are never sent to the model — agent-loop.js strips the heavy payload
// before building the tool-result message (real cost/context, not just
// noise), and the model can't see pixels in a text result anyway. But the
// model still needs *some* way to put a plot in its own final answer, so
// registerPlots() hands it a small opaque id (`plot-N`) instead, and
// workbench.js (resolveRenderReferences) resolves that id back to the real
// data URL from this same store — client-side, never round-tripped through
// the model.
//
// This same pattern is the template for future "render something in chat"
// tools (charts/tables — see plans/tool-expansion-and-visualization.md §4).

// id -> { src (data URL), code (the call that produced it) }
export const plotStore = new Map();
let nextPlotId = 1;

export function registerPlots(result, code) {
  if (!result || !Array.isArray(result.images) || result.images.length === 0) return result;
  const imageIds = result.images.map((src) => {
    const id = `plot-${nextPlotId++}`;
    plotStore.set(id, { src, code });
    return id;
  });
  return { ...result, imageIds };
}

/** For chat-store.js: snapshot entries + the id counter, mirroring
 * render-store.js's snapshot/restore so restored ids never collide with
 * newly minted ones after a reload. */
export function snapshotPlotStore() {
  return { entries: [...plotStore.entries()], nextPlotId };
}

export function restorePlotStore(snapshot) {
  if (!snapshot) return;
  plotStore.clear();
  for (const [id, payload] of snapshot.entries || []) plotStore.set(id, payload);
  if (typeof snapshot.nextPlotId === "number") nextPlotId = snapshot.nextPlotId;
}
